@@ -2,0 +3,5 @@
+import { sleep as realSleep } from './util.mjs';
+
+const MAX_RETRIES = 3;
+const RETRY_DELAY = 100;
+
@@ -12,4 +17,18 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep } = {}) {
+  const init = { headers: { accept: 'application/json', ...headers } };
+
+  for (let retry = 0; ; retry++) {
+    let res;
+    try {
+      res = await fetch(url, init);
+    } catch (error) {
+      if (retry === MAX_RETRIES) throw error;
+      await sleep(RETRY_DELAY * 2 ** retry);
+      continue;
+    }
+
+    if (res.ok) return res.json();
+    if (res.status < 500 || retry === MAX_RETRIES) throw new HttpError(res.status, url);
+
+    await sleep(RETRY_DELAY * 2 ** retry);
+  }
diff --git a/client.test.mjs b/client.test.mjs
index b10d2e2..75fb9e9 100644
--- a/client.test.mjs
+++ b/client.test.mjs
@@ -19,0 +20,43 @@ test('throws HttpError on non-2xx', async () => {
+test('retries transient HTTP failures with injectable backoff', async () => {
+  const responses = [respond(503), respond(503), respond(200, { sku: 'A1' })];
+  const naps = [];
+  const item = await fetchJson('https://x/items/A1', {
+    fetch: async () => responses.shift(),
+    sleep: async (ms) => naps.push(ms),
+  });
+
+  assert.deepEqual(item, { sku: 'A1' });
+  assert.deepEqual(naps, [100, 200]);
+});
+
+test('retries dropped connections no more than three times', async () => {
+  let calls = 0;
+  const naps = [];
+  const dropped = new Error('connection dropped');
+
+  await assert.rejects(fetchJson('https://x/items/A1', {
+    fetch: async () => {
+      calls++;
+      throw dropped;
+    },
+    sleep: async (ms) => naps.push(ms),
+  }), (err) => err === dropped);
+
+  assert.equal(calls, 4);
+  assert.deepEqual(naps, [100, 200, 400]);
+});
+
+test('does not retry client errors', async () => {
+  let calls = 0;
+
+  await assert.rejects(fetchJson('https://x/items/nope', {
+    fetch: async () => {
+      calls++;
+      return respond(404);
+    },
+    sleep: async () => assert.fail('4xx response should not sleep'),
+  }), (err) => err instanceof HttpError && err.status === 404);
+
+  assert.equal(calls, 1);
+});
+

