+const RETRIES = 3;
+const BACKOFF_MS = 100;
+
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep } = {}) {
+  for (let attempt = 0; ; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        if (res.status < 500 || attempt === RETRIES) throw new HttpError(res.status, url);
+      } else {
+        return res.json();
+      }
+    } catch (err) {
+      if (err instanceof HttpError || attempt === RETRIES) throw err;
+    }
+    await sleep(BACKOFF_MS * (2 ** attempt));
+  }
