+
+test('retries dropped connections but not 4xx responses', async () => {
+  let calls = 0;
+  const naps = [];
+  const item = await fetchJson('https://x/items/A1', {
+    fetch: async () => {
+      calls++;
+      if (calls === 1) throw new Error('connection dropped');
+      return respond(200, { sku: 'A1' });
+    },
+    sleep: async (ms) => naps.push(ms),
+  });
+  assert.deepEqual(item, { sku: 'A1' });
+  assert.deepEqual(naps, [100]);
+
+  calls = 0;
+  await assert.rejects(fetchJson('https://x/items/nope', {
+    fetch: async () => {
+      calls++;
+      return respond(404);
+    },
+    sleep: async () => assert.fail('4xx response was retried'),
+  }), (err) => err instanceof HttpError && err.status === 404);
+  assert.equal(calls, 1);
+});
+
